namespace M1.Ax.Erp.JobSchedule.WorkingDays;

public static class WorkingDaysQueries
{
	public const string GetWorkingDaysFromProductionCalendarDays = "SELECT jmyproductioncalendarday, jmyproductioncalendarmonth, jmyProductionCalendarYearID, jmyhours \r\n              FROM productioncalendardays                                                                       \r\n              WHERE DATEFROMPARTS (jmyproductioncalendaryearid, jmyProductionCalendarMonth, jmyProductionCalendarDay ) BETWEEN @StartDate AND @EndDate\r\n                    AND jmyplantid = @PlantID                                                                    \r\n                    AND jmyworkcenterid = @WorkCenterID                                                                   \r\n              ORDER BY jmyproductioncalendarmonth, jmyproductioncalendarday, jmyProductionCalendarYearID";

	public const string GetDefaultNonWorkingDays = "SELECT xawhoursmon HoursMon, xawhourstue HoursTue, xawhourswed HoursWed, \r\n                                                              xawhoursthu HoursThu, xawhoursfri HoursFri, xawhourssat HoursSat, \r\n                                                              xawhourssun HoursSun                                             \r\n                                                         FROM   workcenters                                                       \r\n                                                         WHERE  xawworkcenterid = @WorkCenterId                                   \r\n                                                                AND xawEnableCalendar = 1                                         \r\n                                                         UNION ALL                                                                \r\n                                                         SELECT xauhoursmon HoursMon, xauhourstue HoursTue, xauhourswed HoursWed, \r\n                                                                xauhoursthu HoursThu, xauhoursfri HoursFri, xauhourssat HoursSat, \r\n                                                                xauhourssun HoursSun                                              \r\n                                                         FROM plants                                                              \r\n                                                         WHERE xauplantid = @PlantID                                              \r\n                                                         UNION ALL                                                                \r\n                                                         SELECT xadhoursmon HoursMon, xadhourstue HoursTue, xadhourswed HoursWed, \r\n                                                                xadhoursthu HoursThu, xadhoursfri HoursFri, xadhourssat HoursSat, \r\n                                                                xadhourssun HoursSun                                              \r\n                                                         FROM   datasetproperties";
}
